```cpp
class MyVector {
    char* data;
    size_t size;
public:
    // ... other members ...
    MyVector(MyVector&& other) noexcept : data(nullptr), size(0) {
        data = other.data;
        size = other.size;
        other.data = nullptr;
        other.size = 0;
    }
};
```
The `noexcept` specifier is important because moving resources should generally not throw exceptions.

```cpp
class MyVector {
    char* data;
    size_t size;
public:
    // ... other members ...
    MyVector& operator=(MyVector&& other) noexcept {
        if (this != &other) { // Self-assignment check
            delete[] data;    // Release own resources
            data = other.data; // Steal resources
            size = other.size;
            other.data = nullptr; // Nullify source
            other.size = 0;
        }
        return *this;
    }
};
```
Again, `noexcept` is crucial. The self-assignment check `if (this != &other)` prevents an object from deleting its own resources before stealing them if assigned to itself.
